// localStorage - persists even after closing browser
localStorage.setItem('username', 'John');
console.log(localStorage.getItem('username')); // 'John'
localStorage.removeItem('username');

// sessionStorage - cleared when tab is closed
sessionStorage.setItem('formStep', '2');
console.log(sessionStorage.getItem('formStep')); // '2'
sessionStorage.clear();

if (navigator.geolocation) {
  navigator.geolocation.getCurrentPosition(
    function(position) {
      console.log('Latitude: ' + position.coords.latitude);
      console.log('Longitude: ' + position.coords.longitude);
    },
    function(error) {
      console.log('Error getting location: ' + error.message);
    }
  );
} else {
  console.log('Geolocation is not supported by this browser.');
}

// Drag and Drop example
<div id="box" draggable="true" ondragstart="event.dataTransfer.setData('text', event.target.id)">Drag me</div>
<div id="dropZone" ondrop="drop(event)" ondragover="event.preventDefault()">Drop here</div>

<script>
  function drop(e) {
    e.preventDefault();
    const id = e.dataTransfer.getData('text');
    e.target.appendChild(document.getElementById(id));
  }
</script>

